begin;
set local timezone='America/Bahia';
select no_plan();
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values('b11a4000-0000-4000-8000-000000000001','authenticated','authenticated','quality-composition@example.test','',now(),'{}','{"name":"Quality Composition QA","company_name":"Quality Composition QA"}',now(),now());
select set_config('request.jwt.claims','{"sub":"b11a4000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into public.products(id,company_id,name,pricing_type,base_cost,sales_price,stock_controlled,current_stock,min_stock) values('jc-root',private.current_company_id(),'Produto composto QA','unidade',0,50,false,0,0),('jc-material',private.current_company_id(),'Material base QA','unidade',2,5,true,100,0),('jc-optional',private.current_company_id(),'Opcional QA','unidade',1,3,true,100,0);
select public.composite_command(gen_random_uuid(),'bom_save',jsonb_build_object('product_id','jc-root','structure_type','composite','updated_at',(select updated_at from public.products where id='jc-root'),'components','[{"id":"b11a4100-0000-4000-8000-000000000001","component_product_id":"jc-material","component_type":"material","quantity":2,"unit":"unidade","basis":"unit","waste_percent":5},{"id":"b11a4100-0000-4000-8000-000000000002","component_product_id":"jc-optional","component_type":"material","quantity":1,"unit":"unidade","basis":"unit","is_optional":true}]'::jsonb));
insert into public.orders(id,company_id,customer_name,number,status,total_amount,paid_amount,payment_status,deadline,updated_at) values('jc-order',private.current_company_id(),'Cliente composição QA','PED-JC','producao',500,0,'pendente',now()+interval '2 days','2000-01-01');
insert into public.order_items(id,order_id,product_id,product_name,quantity,unit_price,total_price,details) values('jc-item','jc-order','jc-root','Produto composto QA',10,50,500,'{}');
select public.composite_command(gen_random_uuid(),'optional_select',jsonb_build_object('order_item_id','jc-item','expected_order_updated_at',(select updated_at from public.orders where id='jc-order'),'selected','["b11a4100-0000-4000-8000-000000000002"]'::jsonb));
select public.ensure_production_queue_for_order('jc-order');
select public.composite_command(gen_random_uuid(),'consume','{"order_item_id":"jc-item"}');
select set_config('jc.original',(select jsonb_agg(to_jsonb(x) order by x.id)::text from public.component_consumptions x where order_item_id='jc-item'),true);
select is((select current_stock from public.products where id='jc-material'),79::numeric,'original ten units consume base 20 plus 5 percent waste');
select is((select current_stock from public.products where id='jc-optional'),90::numeric,'original selected optional consumed once');
update public.production_queue set status='concluido' where order_item_id='jc-item';
select set_config('jc.id',public.quality_command(gen_random_uuid(),'create',jsonb_build_object('source_type','production','source_id',(select id from public.production_queue where order_item_id='jc-item'),'source_updated_at',public.quality_origins('production','',0,(select id from public.production_queue where order_item_id='jc-item'))#>>'{origin,version}','description','Duas unidades com defeito no composto QA','category','production_error','severity','medium','affected_quantity',2,'assigned_profile_id',(select id from public.profiles where auth_user_id=auth.uid()),'cost_applicable',true))->>'id',true);
create function pg_temp.jc(a text,patch jsonb default '{}') returns jsonb language sql as $$select public.quality_command(gen_random_uuid(),a,(select jsonb_build_object('id',id,'updated_at',updated_at) from public.quality_nonconformities where id=current_setting('jc.id')::uuid)||patch)$$;
select pg_temp.jc('analyze','{"root_cause":"Ajuste físico incorreto","analysis":"Conferência do composto e opcionais"}');
select pg_temp.jc('action_define',jsonb_build_object('kind','reproduction','execution_mode','internal','quantity',2,'assigned_profile_id',(select id from public.profiles where auth_user_id=auth.uid()),'notes','Reproduzir duas unidades com configuração original'));
select pg_temp.jc('action_start',jsonb_build_object('production_updated_at',(select updated_at from public.production_queue where order_item_id='jc-item')));
select is((select (r->>'required')::numeric from jsonb_array_elements(public.quality_source(current_date,current_date,current_setting('jc.id')::uuid)->'requirements') r where r->>'product_id'='jc-material'),4.2::numeric,'partial rework scales original BOM and loss to affected quantity');
select is((select (r->>'required')::numeric from jsonb_array_elements(public.quality_source(current_date,current_date,current_setting('jc.id')::uuid)->'requirements') r where r->>'product_id'='jc-optional'),2::numeric,'selected physical optional remains part of partial rework');
select is((select current_stock from public.products where id='jc-material'),79::numeric,'restart never repeats original BOM debit');
select pg_temp.jc('material_consume','{"product_id":"jc-material","quantity":4.2}');
select is((select current_stock from public.products where id='jc-material'),74.8::numeric,'only explicit additional material debits stock');
select is((select jsonb_agg(to_jsonb(x) order by x.id)::text from public.component_consumptions x where order_item_id='jc-item'),current_setting('jc.original'),'original consumption and costs remain byte-for-byte unchanged');
select throws_like($$select public.composite_command(gen_random_uuid(),'optional_select',jsonb_build_object('order_item_id','jc-item','expected_order_updated_at',(select updated_at from public.orders where id='jc-order'),'selected','[]'::jsonb))$$,'%histórico%','NC physical history prevents rewriting original optional selection');
select is((select count(*) from public.production_queue where order_id='jc-order'),1::bigint,'composite reproduction uses one canonical queue');
select is((select quantity from public.order_items where id='jc-item'),10::numeric,'original commercial quantity remains ten');
select * from finish();rollback;
